add('n19','角色属性','动态属性血量','量表保存生命最大值、最小值与当前值；伤害或恢复后界面显示对应生命变化，仍沿用原量表对象。','10:3.2;HP:ATTR-HP-001',original='n19')
add('n25','角色属性','血量变化触发状态刷新','量表发生已提交变动时广播原图约定的变化消息；订阅它的状态呈现及时反映新生命值。受伤和目标判定在各自节点中验收。','10:3.2、3.5',original='n25')
add('n29','角色属性','生命阈值与伤势升级','生命低于配置限度时呈现受伤生命状态，并使伤势档位提升一档；伤势显示轻伤、重伤、致残。阈值跨越重复触发口径待 G03 裁定；不把原图固定 20% 伤害或二级伤势死亡作为正式规则。','10:3.2;HP:ATTR-WOUND-001','', 'n29',blockers='G03 G09')
add('n13','时间轴','多角色共用时间轴','设置多角色并保留原图的隐性时间轴阶段；全部敌我单位在同一条时间轴上获得行动机会，详情能识别当前行动者。正式后摇与速度合成见本路线后续条目。','20:3.1',original='n13')
add('n14','时间轴','制作时间轴UI','按配置限定未来显示次数，呈现将获行动机会的单位及本单位预计时机；超出配置显示范围的部分不展示。','20:3.5',original='n14',blockers='G09')
