add('n7','角色技能','防御待机','当前行动者选择并确认防御待机后，按其配置进入防御状态并结束本次行动；按待机类别追加字母且按配置后摇回排时间轴。保留动作并列与技能容器组件；具体确认操作见行为交互。','85:3.3、3.5;BHV:BHV-IDLE-001',original='n7',blockers='G09')
add('n8','角色技能','指定敌对目标固定伤害','选择原图固定值伤害技能并确认合法敌方目标后，扣减该目标配置的固定生命值并显示变化。固定伤害值沿用输入；该节点仅验收指定目标伤害，另外三类原试验由技能效果试验路线承接。','BHV:BHV-SKILL-001;40:8',original='n8',blockers='G09')
add('n23','角色技能','技能可选范围预览','选择技能后以外框线显示纯射程可选地格范围，沿用原图范围预览方式；它与目标是否合法分别判定，取消选择后退出预览。受影响范围另在行为交互中验收。','30:3.4;40:7',original='n23')
add('n24','角色技能','每单位独立行动槽','我方每个单位独立保存已提交行动的类别序列；切换查看单位时显示对应序列，彼此不串用。正式追加、容量与打断规则由行动槽规则路线承接。','50:3.1、3.5',original='n24')
add('n26','角色技能','连携成本与产出循环','在原连携构建阶段，选择已满足成本串的连携并确认后，消耗槽尾成本、执行技能效果并追加产出串；先保留无继承效果的阶段，继承效果在后续节点正式补齐。','50:3.2;40:6',original='n26')
add('n27','角色技能','角色行为面板并列展示','当前行动者面板沿用原图平铺并列层级：移动一项、待机一项、四个基础技能和五个连携技能；分别的移动、待机、定向与非定向技能操作由行为交互路线承接。搜刮、场景交互和撤退保持各自可发现入口。','10:3.6;40:3.1、7;85:3.1',original='n27',blockers='G12')
add('n28','角色技能','基础技能继承效果','已配置基础技能为产出对应动作类型的行为提供继承效果；基础技能被替换、配置生效时重算，技能详情显示当前构筑的最终效果。局外配置流程以预置构筑代入。','40:6、7;EFF:EFF-INHERIT-001',original='n28',blockers='G09')
add('n22','敌人ai','敌我行动切换','保留原图最近敌对目标移动与待机的占位动作：轮到敌人时自动执行，行动结束后按共享时间轴转到下一行动者。正式模板行为由后续条目补齐。','90:3.1',original='n22')

